/** `addr@dom.tld` or `Name <addr@dom.tld>` — anything else is not sendable. */
function validEmailSender(v: string): boolean {
  const s = v.trim();
  if (!s) return false;
  return /^[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+$/.test(s) || /^[^<>]+<[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+>$/.test(s);
}

